<?php
require_once __DIR__ . '/inc/connect.php';
require_once __DIR__ . '/inc/auth.php';
require_once __DIR__ . '/inc/maternal_intelligence.php';
$role=(int)$_SESSION['log_role'];$uid=(int)$_SESSION['u_id'];$facility=(int)($_SESSION['facility_id']??0);
if($role===3){$scope='(a.assigned_to=? OR m.chw_id=?)';$params=[$uid,$uid];}
elseif($role===2){$scope='(a.assigned_to=? OR a.facility_id=?)';$params=[$uid,$facility];}
elseif($role===4){$scope='m.facility_id=?';$params=[$facility];}
else{$scope='1=1';$params=[];}
$sql="SELECT a.alert_id,a.report_id,a.alert_level,a.alert_message,a.status,a.created_at,a.assigned_to,a.facility_id,
       m.mother_id,m.f_name,m.l_name,m.phone,m.chw_id,m.facility_id mother_facility_id,
       r.symptoms_json,r.severity,r.additional_notes,r.reported_temperature,r.reported_systolic,r.reported_diastolic,r.reference_code,
       ra.summary_text,ra.review_status analysis_review_status,ra.analysis_version,
       p.pregnancy_id,p.lmp,p.edd,p.dating_source,p.dating_confidence,p.pregnancy_status
       FROM tbl_alerts a JOIN tbl_mothers m ON m.mother_id=a.mother_id
       LEFT JOIN tbl_symptom_reports r ON r.report_id=a.report_id
       LEFT JOIN tbl_report_analyses ra ON ra.report_id=r.report_id
       LEFT JOIN tbl_pregnancies p ON p.pregnancy_id=a.pregnancy_id
       WHERE a.status IN ('open','acknowledged','escalated') AND $scope
       ORDER BY FIELD(a.alert_level,'critical','high','medium','low'),a.created_at DESC LIMIT 50";
$q=$db->prepare($sql);$q->execute($params);$alerts=$q->fetchAll(PDO::FETCH_ASSOC);
$countSql="SELECT COUNT(*) total_count,SUM(a.alert_level='critical') critical_count,SUM(a.alert_level='high') high_count,SUM(a.status='escalated') escalated_count FROM tbl_alerts a JOIN tbl_mothers m ON m.mother_id=a.mother_id WHERE a.status IN ('open','acknowledged','escalated') AND $scope";
$countQuery=$db->prepare($countSql);$countQuery->execute($params);$alertCounts=$countQuery->fetch(PDO::FETCH_ASSOC)?:[];
$totalAlerts=(int)($alertCounts['total_count']??0);$criticalCount=(int)($alertCounts['critical_count']??0);$highCount=(int)($alertCounts['high_count']??0);$escalatedCount=(int)($alertCounts['escalated_count']??0);
$page_title='Maternal intelligence review';include 'inc/links.php';include 'inc/header.php';
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php'; ?><section role="main" class="content-body"><?php include 'inc/inner-header.php'; ?>
<div class="mcare-intel-intro"><div><span class="mcare-intel-eyebrow">CARE TEAM WORKSPACE</span><h1>Maternal intelligence review</h1><p>Review active alerts alongside the mother’s recorded report, pregnancy details, and information gaps.</p></div><div class="mcare-intel-note"><i class="fa fa-info-circle" aria-hidden="true"></i><span>Professional review support. This page organizes recorded information; it does not diagnose or recommend treatment. Follow approved local protocols.</span></div></div>
<div class="mcare-intel-metrics"><div class="mcare-intel-metric"><span>Active alerts in your scope</span><strong><?=$totalAlerts?></strong></div><div class="mcare-intel-metric mcare-intel-metric-critical"><span>Critical</span><strong><?=$criticalCount?></strong></div><div class="mcare-intel-metric mcare-intel-metric-high"><span>High priority</span><strong><?=$highCount?></strong></div><div class="mcare-intel-metric"><span>Escalated</span><strong><?=$escalatedCount?></strong></div></div>
<?php if($totalAlerts>count($alerts)): ?><p class="mcare-intel-list-note">Showing the most recent <?=count($alerts)?> of <?=$totalAlerts?> active alerts.</p><?php endif; ?>
<?php if(!$alerts): ?><section class="mcare-intel-empty"><span class="mcare-intel-empty-icon"><i class="fa fa-check" aria-hidden="true"></i></span><h2>No active alerts</h2><p>There are no open maternal alerts in your assigned scope.</p></section><?php endif; ?>
<?php foreach($alerts as $a):
    $pregnancy=$a['pregnancy_id']?['edd'=>$a['edd'],'lmp'=>$a['lmp'],'dating_source'=>$a['dating_source'],'dating_confidence'=>$a['dating_confidence']]:[];
    $history=null;$latestAnc=null;
    $eventQuery=$db->prepare('SELECT event_type,to_user_id,event_note,created_at FROM tbl_alert_events WHERE alert_id=? ORDER BY created_at DESC,alert_event_id DESC LIMIT 15');$eventQuery->execute([(int)$a['alert_id']]);$alertEvents=$eventQuery->fetchAll(PDO::FETCH_ASSOC);
    if($a['pregnancy_id']){$h=$db->prepare('SELECT * FROM tbl_maternal_history WHERE pregnancy_id=? ORDER BY created_at DESC LIMIT 1');$h->execute([(int)$a['pregnancy_id']]);$history=$h->fetch(PDO::FETCH_ASSOC)?:null;
        $v=$db->prepare('SELECT visit_date,bp_systolic,bp_diastolic,weight,temperature_c,hiv_status,syphilis_status FROM tbl_anc_visits WHERE pregnancy_id=? ORDER BY visit_date DESC,anc_id DESC LIMIT 1');$v->execute([(int)$a['pregnancy_id']]);$latestAnc=$v->fetch(PDO::FETCH_ASSOC)?:null;}
    $summary=$a['pregnancy_id']?mcare_maternal_summary($pregnancy,$history,$latestAnc):['gestational_age_weeks'=>null,'trimester'=>null,'dating_source'=>'unknown','dating_confidence'=>'unknown','estimated_due_date'=>null,'historical_risk_factors'=>[],'latest_anc'=>null,'information_gaps'=>['No pregnancy episode is linked to this alert.'],'clinical_interpretation'=>'Not provided. This is a summary of recorded data for a qualified professional to review.'];
    $symptomNames=[];$ids=array_values(array_filter(array_map('intval',json_decode((string)$a['symptoms_json'],true)?:[])));if($ids){$s=$db->prepare('SELECT symptom_name FROM tbl_symptoms WHERE symptom_id IN ('.implode(',',array_fill(0,count($ids),'?')).')');$s->execute($ids);$symptomNames=$s->fetchAll(PDO::FETCH_COLUMN);}
?>
<article class="mcare-intel-card"><header class="mcare-intel-card-head"><div class="mcare-intel-person"><span class="mcare-intel-priority mcare-priority-<?=htmlspecialchars($a['alert_level'])?>"><?=htmlspecialchars(strtoupper($a['alert_level']))?></span><div><h2><?=htmlspecialchars($a['f_name'].' '.$a['l_name'])?></h2><span><?=htmlspecialchars($a['reference_code']?:'Alert '.$a['alert_id'])?></span></div></div><div class="mcare-intel-alert-meta"><span class="mcare-intel-status mcare-status-<?=htmlspecialchars($a['status'])?>"><?=htmlspecialchars(ucfirst($a['status']))?></span><time><?=htmlspecialchars($a['created_at'])?></time></div></header><div class="mcare-intel-card-body">
<?php if(!empty($a['alert_message'])): ?><div class="mcare-intel-alert-message"><?=nl2br(htmlspecialchars($a['alert_message']))?></div><?php endif; ?>
<div class="mcare-intel-content-grid"><section class="mcare-intel-section"><h3><i class="fa fa-file-text-o" aria-hidden="true"></i> Submitted report</h3><div class="mcare-intel-field"><span>Reported symptoms</span><div class="mcare-intel-tags"><?php if($symptomNames): foreach($symptomNames as $symptomName): ?><span><?=htmlspecialchars($symptomName)?></span><?php endforeach; else: ?><span class="mcare-intel-muted">No catalogue symptoms recorded</span><?php endif; ?></div></div><?php if($a['severity']): ?><div class="mcare-intel-field"><span>Self-described severity</span><strong><?=htmlspecialchars(ucfirst($a['severity']))?></strong></div><?php endif; ?><?php if($a['reported_temperature']!==null||$a['reported_systolic']!==null||$a['reported_diastolic']!==null): ?><div class="mcare-intel-field"><span>Reported readings</span><strong><?php if($a['reported_temperature']!==null): ?>Temperature <?=htmlspecialchars((string)$a['reported_temperature'])?> °C<?php endif; ?><?php if($a['reported_systolic']!==null||$a['reported_diastolic']!==null): ?> · BP <?=htmlspecialchars(($a['reported_systolic']??'—').'/'.($a['reported_diastolic']??'—'))?><?php endif; ?></strong></div><?php endif; ?><?php if($a['additional_notes']): ?><div class="mcare-intel-field"><span>Mother’s notes</span><p><?=nl2br(htmlspecialchars($a['additional_notes']))?></p></div><?php endif; ?></section>
<section class="mcare-intel-section"><h3><i class="fa fa-heart-o" aria-hidden="true"></i> Pregnancy and ANC</h3><?php if($summary['gestational_age_weeks']!==null): ?><div class="mcare-intel-gestation"><strong><?= (int)$summary['gestational_age_weeks'] ?></strong><span>weeks estimated · trimester <?= (int)$summary['trimester'] ?></span></div><?php else: ?><p class="mcare-intel-muted">Gestational age cannot be estimated from recorded dates.</p><?php endif; ?><div class="mcare-intel-field"><span>Estimated due date</span><strong><?=htmlspecialchars($summary['estimated_due_date']?:'Not recorded')?></strong></div><div class="mcare-intel-field"><span>Dating details</span><strong><?=htmlspecialchars(ucwords(str_replace('_',' ',$summary['dating_source'])))?> · <?=htmlspecialchars(ucfirst($summary['dating_confidence']))?> confidence</strong></div><?php if($latestAnc): ?><div class="mcare-intel-field"><span>Latest ANC · <?=htmlspecialchars($latestAnc['visit_date'])?></span><strong>BP <?=htmlspecialchars(($latestAnc['bp_systolic']??'—').'/'.($latestAnc['bp_diastolic']??'—'))?> · Temp <?=htmlspecialchars($latestAnc['temperature_c']??'—')?> °C</strong></div><?php else: ?><div class="mcare-intel-field"><span>Latest ANC</span><strong class="mcare-intel-muted">No ANC visit recorded</strong></div><?php endif; ?></section></div>
<?php if($summary['historical_risk_factors']): ?><section class="mcare-intel-inline"><strong>Recorded history for review</strong><div class="mcare-intel-tags"><?php foreach($summary['historical_risk_factors'] as $factor): ?><span><?=htmlspecialchars(ucwords(str_replace('_',' ',$factor)))?></span><?php endforeach; ?></div></section><?php endif; ?>
<?php if(!empty($a['summary_text'])): ?><section class="mcare-intel-auto-summary"><div><strong>Automated intake summary</strong><span class="mcare-intel-review-status">Review status: <?=htmlspecialchars(ucfirst((string)$a['analysis_review_status']))?></span></div><p><?=nl2br(htmlspecialchars($a['summary_text']))?></p><small>Structured summary of submitted report fields and recent report overlap. Not a diagnosis.</small></section><?php endif; ?>
<section class="mcare-intel-gaps"><div><h3>Information gaps</h3><p>Recorded items a professional may want to check.</p></div><ul><?php foreach($summary['information_gaps'] as $gap): ?><li><?=htmlspecialchars($gap)?></li><?php endforeach; ?></ul></section><p class="mcare-intel-interpretation"><?=htmlspecialchars($summary['clinical_interpretation'])?></p>
<footer class="mcare-intel-actions"><a class="btn btn-primary" href="mother_profile?id=<?=(int)$a['mother_id']?>"><i class="fa fa-user-o" aria-hidden="true"></i> Open maternal profile</a><a class="btn btn-default" href="alerts?id=<?=(int)$a['alert_id']?>"><i class="fa fa-external-link" aria-hidden="true"></i> Open alert workflow</a><details class="mcare-intel-history"><summary><i class="fa fa-history" aria-hidden="true"></i> Response history (<?=count($alertEvents)?>)</summary><ul><?php foreach($alertEvents as $ev): ?><li><time><?=htmlspecialchars($ev['created_at'])?></time> · <?=htmlspecialchars(ucfirst($ev['event_type']))?><?php if($ev['to_user_id']): ?> (user #<?= (int)$ev['to_user_id']?>)<?php endif; ?><?php if($ev['event_note']): ?>: <?=htmlspecialchars($ev['event_note'])?><?php endif; ?></li><?php endforeach; ?><?php if(!$alertEvents): ?><li>No response history recorded.</li><?php endif; ?></ul></details></footer>
</div></article><?php endforeach; ?>
</section></div><?php include 'inc/footer.php';include 'inc/scripts.php'; ?>
